-- Delivery corrections only: preserve main questions, keys, answers and completed attempts.
BEGIN;
UPDATE "test_versions" SET "delivery" = jsonb_set("delivery", '{practice}', $practice$[{"text":{"ru":"Выберите недостающий элемент.","kk":"Жетіспейтін элементті таңдаңыз."},"imageUrl":"/api/assets/omib/v2-item-1.svg","options":[{"ru":"Вариант 1","kk":"1-нұсқа"},{"ru":"Вариант 2","kk":"2-нұсқа"},{"ru":"Вариант 3","kk":"3-нұсқа"},{"ru":"Вариант 4","kk":"4-нұсқа"},{"ru":"Вариант 5","kk":"5-нұсқа"},{"ru":"Вариант 6","kk":"6-нұсқа"}],"images":["/api/assets/omib/v2-item-1-option-09d0fec4946895cd.svg","/api/assets/omib/v2-item-1-option-f14892ebcaddef3e.svg","/api/assets/omib/v2-item-1-option-7082ddf495f7b84f.svg","/api/assets/omib/v2-item-1-option-0e0e4455f819f195.svg","/api/assets/omib/v2-item-1-option-4a5cbd5f3feac4df.svg","/api/assets/omib/v2-item-1-option-9294e69140996a2d.svg"],"correct":2,"explanation":{"ru":"В каждой строке фигуры первой и второй клетки складываются.","kk":"Әр жолда бірінші және екінші ұяшықтағы фигуралар қосылады."}},{"text":{"ru":"Выберите недостающий элемент.","kk":"Жетіспейтін элементті таңдаңыз."},"imageUrl":"/api/assets/omib/v2-item-11.svg","options":[{"ru":"Вариант 1","kk":"1-нұсқа"},{"ru":"Вариант 2","kk":"2-нұсқа"},{"ru":"Вариант 3","kk":"3-нұсқа"},{"ru":"Вариант 4","kk":"4-нұсқа"},{"ru":"Вариант 5","kk":"5-нұсқа"},{"ru":"Вариант 6","kk":"6-нұсқа"}],"images":["/api/assets/omib/v2-item-11-option-86d314e7344e2227.svg","/api/assets/omib/v2-item-11-option-b5206094e5e7a477.svg","/api/assets/omib/v2-item-11-option-6a2e138777c754a3.svg","/api/assets/omib/v2-item-11-option-ae9032ad23db0907.svg","/api/assets/omib/v2-item-11-option-f6f187c506f23439.svg","/api/assets/omib/v2-item-11-option-435da079c4ac1d87.svg"],"correct":4,"explanation":{"ru":"Фигура поворачивается на один и тот же угол из клетки в клетку.","kk":"Фигура ұяшықтан ұяшыққа бірдей бұрышқа бұрылады."}}]$practice$::jsonb) WHERE "testId" = 'logical' AND "version" = '2.0-2026-10-26';
UPDATE "test_versions" SET "timeLimitSeconds" = NULL, "instructions" = $instructions${"ru":"Оцените, насколько каждое утверждение описывает вас в обычной жизни и работе. 1 — совсем не про меня; 2 — скорее не про меня; 3 — отчасти про меня; 4 — скорее про меня; 5 — точно про меня. Правильных и неправильных ответов нет. Время не ограничено, ответы сохраняются.","kk":"Әр тұжырымның сізді күнделікті өмірде және жұмыста қаншалықты сипаттайтынын бағалаңыз. 1 — мүлдем мен туралы емес; 2 — көбіне мен туралы емес; 3 — ішінара мен туралы; 4 — көбіне мен туралы; 5 — дәл мен туралы. Дұрыс немесе бұрыс жауаптар жоқ. Уақыт шектелмейді, жауаптар сақталады."}$instructions$::jsonb WHERE "testId" = 'personality' AND "version" = '2.0-2026-10-26';
UPDATE "test_versions" SET "timeLimitSeconds" = NULL, "instructions" = $instructions${"ru":"В этом опроснике нет правильных и неправильных ответов. Мы хотим понять, что именно в работе даёт вам энергию, а что её забирает. Результаты используются для плана развития, а не для оценки вашей работы.\n\nЧасть 1. Прочитайте каждое утверждение и отметьте, как это условие влияет на ваше желание работать: снижает, не влияет или повышает. Оценивайте не то, есть ли это сейчас в вашей работе, а то, как бы это на вас подействовало. Отвечайте в удобном для вас темпе, ориентируясь на своё обычное отношение к работе.\n\nЧасть 2. Из 12 карточек выберите 3, которые для вас важнее всего, и 3, которые важны меньше всего. Всё сразу важным быть не может — нам нужны ваши приоритеты.\n\nВремя не ограничено, обычно уходит 10–12 минут. Можно сделать перерыв и вернуться.\n\nПример перед стартом (не засчитывается): «Комфортный и современный офис». Если это вас немного вдохновляет — выберите 4; если безразлично — 3.","kk":"Бұл сауалнамада дұрыс немесе бұрыс жауап жоқ. Біз жұмыста сізге не қуат беретінін, ал не оны алатынын түсінгіміз келеді. Нәтижелер сіздің жұмысыңызды бағалау үшін емес, даму жоспары үшін пайдаланылады.\n\n1-бөлім. Әр тұжырымды оқып, бұл жағдай сіздің жұмыс істеуге деген ықыласыңызға қалай әсер ететінін белгілеңіз: төмендетеді, әсер етпейді немесе арттырады. Бұл қазір сіздің жұмысыңызда бар-жоғын емес, оның сізге қалай әсер ететінін бағалаңыз. Өзіңізге ыңғайлы қарқынмен жауап беріп, жұмысқа деген әдеттегі көзқарасыңызға сүйеніңіз.\n\n2-бөлім. 12 карточканың ішінен сіз үшін ең маңызды 3 карточканы және ең аз маңызды 3 карточканы таңдаңыз. Бәрі бірдей маңызды бола алмайды — бізге сіздің басымдықтарыңыз керек.\n\nУақыт шектелмейді, әдетте 10–12 минут кетеді. Үзіліс жасап, қайта оралуға болады.\n\nБастар алдындағы мысал (есепке алынбайды): «Жайлы әрі заманауи кеңсе». Егер бұл сізді аздап шабыттандырса — 4-ті таңдаңыз; егер бәрібір болса — 3-ті."}$instructions$::jsonb WHERE "testId" = 'motivation' AND "version" = '2.0-2026-10-26';
UPDATE "test_versions" SET "delivery" = jsonb_set("delivery", '{practice}', $practice$[{"text":{"ru":"Ситуация. Вы — директор филиала. В понедельник утром вы узнаёте, что специалист, отвечающий за приём заявок, заболел на неделю. На эту неделю у него записаны 12 заявителей, два других специалиста загружены примерно на 70%.","kk":"Жағдай. Сіз — филиал директорысыз. Дүйсенбі күні таңертең өтінімдерді қабылдауға жауапты маманның бір аптаға ауырып қалғанын білесіз. Осы аптаға оған 12 өтініш беруші жазылған, қалған екі маманның жүктемесі шамамен 70%."},"options":[{"ru":"Перенести всех записанных заявителей на следующую неделю и сообщить им об этом по телефону.","kk":"Жазылған барлық өтініш берушілерді келесі аптаға ауыстырып, бұл туралы оларға телефон арқылы хабарлау."},{"ru":"Распределить заявителей между двумя специалистами с учётом их загрузки и передать им досье.","kk":"Өтініш берушілерді екі маманның жүктемесін ескере отырып, олардың арасында бөліп, досьелерді оларға беру."},{"ru":"Принимать заявителей самому, отложив на неделю свои текущие задачи и совещания с ГО.","kk":"Ағымдағы міндеттерім мен бас кеңсемен (БК) өткізілетін кеңестерді бір аптаға кейінге қалдырып, өтініш берушілерді өзім қабылдау."},{"ru":"Запросить у ГО временного сотрудника и до его приезда не менять запись заявителей.","kk":"Бас кеңседен (БК) уақытша қызметкер сұрату және ол келгенге дейін өтініш берушілердің жазылуын өзгертпеу."}],"type":"sjt","explanation":{"ru":"В этой тренировочной ситуации наиболее эффективно — B: распределить заявителей между двумя специалистами с учётом их загрузки. Это позволяет сохранить сроки приёма. Наименее эффективно — A: перенести всех заявителей на неделю, хотя у филиала есть свободный ресурс. Этот разбор относится только к тренировке; в основном тесте каждую ситуацию оценивайте отдельно.","kk":"Осы жаттығу жағдайында ең тиімді нұсқа — B: өтініш берушілерді екі маманның жүктемесін ескере отырып бөлу. Бұл қабылдау мерзімдерін сақтауға мүмкіндік береді. Ең тиімсіз нұсқа — A: филиалда бос ресурс бола тұра, барлық өтініш берушіні келесі аптаға ауыстыру. Бұл талдау тек жаттығуға қатысты; негізгі тестте әр жағдайды жеке бағалаңыз."},"correctMost":1,"correctLeast":0}]$practice$::jsonb) WHERE "testId" = 'situations' AND "version" = '2.0-2026-10-26';
UPDATE "test_attempts" AS a SET "expiresAt" = NULL, "pausedAt" = NULL
FROM "test_assignments" AS s JOIN "test_versions" AS v ON v.id = s."testVersionId"
WHERE a."assignmentId" = s.id AND a.status = 'in_progress'
AND v."testId" IN ('personality', 'motivation') AND v.version = '2.0-2026-10-26';
COMMIT;
